<script>
// ============================================================
// CONFIGURATION
// ============================================================
const W = 800;           // playfield width (inside cushions)
const H = 400;           // playfield height
const R = 12;            // ball radius
const POCKET_R = 22;     // pocket radius
const FRICTION = 0.75;   // rolling friction (px/s^2)
const BALL_RESTITUTION = 0.95;
const CUSHION_RESTITUTION = 0.9;
const MIN_SPEED = 8;     // speed below which ball stops (px/s)
const SUBSTEPS = 4;      // physics sub-steps per frame for stability

// Pocket positions (center of pockets)
const POCKETS = [
  {x: R, y: R},                    // top-left
  {x: W/2, y: R},                  // top-middle
  {x: W-R, y: R},                  // top-right
  {x: R, y: H-R},                  // bottom-left
  {x: W/2, y: H-R},                // bottom-middle
  {x: W-R, y: H-R}                 // bottom-right
];

// Initial rack: 15 balls in triangle + cue ball
function createInitialBalls() {
  const balls = [];
  // Cue ball at head string (1/4 from bottom)
  balls.push({x: W/4, y: H/2, vx: 0, vy: 0, cue: true, potted: false});
  // Racked balls: triangle at foot spot (3/4 from bottom)
  const footX = W * 0.75;
  const footY = H/2;
  const spacing = R * 2.02; // slight gap to avoid initial overlap
  let idx = 0;
  for (let row = 0; row < 5; row++) {
    const rCount = row + 1;
    const startX = footX + row * spacing * 0.866; // sqrt(3)/2 * spacing
    const startY = footY - (rCount - 1) * spacing * 0.5;
    for (let i = 0; i < rCount; i++) {
      balls.push({
        x: startX,
        y: startY + i * spacing,
        vx: 0, vy: 0,
        cue: false, potted: false
      });
    }
  }
  return balls;
}

// ============================================================
// PHYSICS ENGINE
// ============================================================
class PhysicsEngine {
  constructor() {
    this.balls = [];
    this.running = true;
    this.lastTime = 0;
    this.accumulator = 0;
    this.fixedDt = 1/60; // 60 Hz fixed timestep
  }

  reset(ballsData) {
    this.balls = ballsData.map(b => ({
      x: b.x, y: b.y,
      vx: b.vx || 0, vy: b.vy || 0,
      cue: !!b.cue,
      potted: false,
      active: true
    }));
  }

  shoot(vx, vy) {
    const cue = this.balls.find(b => b.cue && b.active);
    if (cue) {
      cue.vx = vx;
      cue.vy = vy;
    }
  }

  state() {
    return this.balls.map(b => ({
      x: b.x, y: b.y,
      vx: b.vx, vy: b.vy,
      potted: b.potted,
      cue: b.cue
    }));
  }

  pause() { this.running = false; }
  resume() { this.running = true; }

  step(dt) {
    if (!this.running) return;
    // Fixed timestep with accumulator for determinism
    this.accumulator += dt;
    while (this.accumulator >= this.fixedDt) {
      this._stepFixed(this.fixedDt);
      this.accumulator -= this.fixedDt;
    }
  }

  _stepFixed(dt) {
    // 1. Apply friction
    for (const b of this.balls) {
      if (!b.active || b.potted) continue;
      const speed = Math.hypot(b.vx, b.vy);
      if (speed > MIN_SPEED) {
        const decel = FRICTION * dt;
        const factor = Math.max(0, 1 - decel / speed);
        b.vx *= factor;
        b.vy *= factor;
      } else {
        b.vx = 0;
        b.vy = 0;
      }
    }

    // 2. Move balls
    for (const b of this.balls) {
      if (!b.active || b.potted) continue;
      b.x += b.vx * dt;
      b.y += b.vy * dt;
    }

    // 3. Cushion collisions (walls)
    for (const b of this.balls) {
      if (!b.active || b.potted) continue;
      // Left/Right
      if (b.x - R < 0) {
        b.x = R;
        b.vx = Math.abs(b.vx) * CUSHION_RESTITUTION;
      } else if (b.x + R > W) {
        b.x = W - R;
        b.vx = -Math.abs(b.vx) * CUSHION_RESTITUTION;
      }
      // Top/Bottom
      if (b.y - R < 0) {
        b.y = R;
        b.vy = Math.abs(b.vy) * CUSHION_RESTITUTION;
      } else if (b.y + R > H) {
        b.y = H - R;
        b.vy = -Math.abs(b.vy) * CUSHION_RESTITUTION;
      }
    }

    // 4. Ball-ball collisions (resolved with sub-stepping for accuracy)
    for (let sub = 0; sub < SUBSTEPS; sub++) {
      const subDt = dt / SUBSTEPS;
      // Move
      for (const b of this.balls) {
        if (!b.active || b.potted) continue;
        b.x += b.vx * subDt;
        b.y += b.vy * subDt;
      }
      // Detect & resolve
      for (let i = 0; i < this.balls.length; i++) {
        const a = this.balls[i];
        if (!a.active || a.potted) continue;
        for (let j = i + 1; j < this.balls.length; j++) {
          const b = this.balls[j];
          if (!b.active || b.potted) continue;
          this._resolveBallCollision(a, b);
        }
      }
      // Cushions again after sub-step move
      for (const b of this.balls) {
        if (!b.active || b.potted) continue;
        if (b.x - R < 0) { b.x = R; b.vx = Math.abs(b.vx) * CUSHION_RESTITUTION; }
        else if (b.x + R > W) { b.x = W - R; b.vx = -Math.abs(b.vx) * CUSHION_RESTITUTION; }
        if (b.y - R < 0) { b.y = R; b.vy = Math.abs(b.vy) * CUSHION_RESTITUTION; }
        else if (b.y + R > H) { b.y = H - R; b.vy = -Math.abs(b.vy) * CUSHION_RESTITUTION; }
      }
    }

    // 5. Pocket checks
    for (const b of this.balls) {
      if (!b.active || b.potted) continue;
      for (const p of POCKETS) {
        const dx = b.x - p.x;
        const dy = b.y - p.y;
        if (dx*dx + dy*dy < POCKET_R * POCKET_R) {
          b.potted = true;
          b.active = false;
          b.vx = 0;
          b.vy = 0;
          break;
        }
      }
    }
  }

  _resolveBallCollision(a, b) {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const dist2 = dx*dx + dy*dy;
    const minDist = 2 * R;
    if (dist2 >= minDist * minDist || dist2 === 0) return;

    const dist = Math.sqrt(dist2);
    // Normal vector
    const nx = dx / dist;
    const ny = dy / dist;

    // Relative velocity
    const dvx = a.vx - b.vx;
    const dvy = a.vy - b.vy;
    const dvn = dvx * nx + dvy * ny;

    // Already separating
    if (dvn > 0) return;

    // Impulse scalar (equal mass, so mass = 1)
    const impulse = (1 + BALL_RESTITUTION) * dvn * 0.5;

    // Apply impulse
    a.vx -= impulse * nx;
    a.vy -= impulse * ny;
    b.vx += impulse * nx;
    b.vy += impulse * ny;

    // Position correction to avoid sticking
    const overlap = minDist - dist;
    const correction = overlap * 0.5;
    a.x -= correction * nx;
    a.y -= correction * ny;
    b.x += correction * nx;
    b.y += correction * ny;
  }
}

// ============================================================
// RENDERER
// ============================================================
class Renderer {
  constructor(canvas, engine) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.engine = engine;
    this.dpr = window.devicePixelRatio || 1;
    this.resize();
    window.addEventListener('resize', () => this.resize());
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    this.canvas.width = rect.width * this.dpr;
    this.canvas.height = rect.height * this.dpr;
    this.ctx.scale(this.dpr, this.dpr);
    this.cssW = rect.width;
    this.cssH = rect.height;
    // Scale factor from physics coords to canvas coords
    this.scaleX = this.cssW / W;
    this.scaleY = this.cssH / H;
    this.scale = Math.min(this.scaleX, this.scaleY);
    this.offsetX = (this.cssW - W * this.scale) / 2;
    this.offsetY = (this.cssH - H * this.scale) / 2;
  }

  px(x) { return this.offsetX + x * this.scale; }
  py(y) { return this.offsetY + y * this.scale; }
  pr(r) { return r * this.scale; }

  draw(aimLine = null) {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.cssW, this.cssH);

    // Table felt
    const feltGrad = ctx.createLinearGradient(0, 0, this.cssW, this.cssH);
    feltGrad.addColorStop(0, '#0f4d2a');
    feltGrad.addColorStop(1, '#0a3d1f');
    ctx.fillStyle = feltGrad;
    ctx.fillRect(this.px(0), this.py(0), W * this.scale, H * this.scale);

    // Cushions (rails)
    const railWidth = this.pr(18);
    const railGrad = ctx.createLinearGradient(0, 0, 0, railWidth);
    railGrad.addColorStop(0, '#3d2b1f');
    railGrad.addColorStop(0.5, '#5d4037');
    railGrad.addColorStop(1, '#3d2b1f');
    ctx.fillStyle = railGrad;
    // Top rail
    ctx.fillRect(this.px(-18), this.py(-18), (W+36)*this.scale, railWidth);
    // Bottom rail
    ctx.fillRect(this.px(-18), this.py(H), (W+36)*this.scale, railWidth);
    // Left rail
    ctx.fillRect(this.px(-18), this.py(-18), railWidth, (H+36)*this.scale);
    // Right rail
    ctx.fillRect(this.px(W), this.py(-18), railWidth, (H+36)*this.scale);

    // Pockets (holes)
    ctx.fillStyle = '#000';
    for (const p of POCKETS) {
      ctx.beginPath();
      ctx.arc(this.px(p.x), this.py(p.y), this.pr(POCKET_R), 0, Math.PI*2);
      ctx.fill();
      // Pocket liner
      ctx.strokeStyle = '#1a1a1a';
      ctx.lineWidth = this.pr(2);
      ctx.stroke();
    }

    // Diamonds (sights) on rails
    ctx.fillStyle = '#fff8';
    const diamondCount = 7;
    for (let i = 1; i <= diamondCount; i++) {
      const frac = i / (diamondCount + 1);
      const dx = W * frac;
      const dy = H * frac;
      const size = this.pr(4);
      // Top
      ctx.fillRect(this.px(dx)-size/2, this.py(-12)-size/2, size, size);
      // Bottom
      ctx.fillRect(this.px(dx)-size/2, this.py(H+12)-size/2, size, size);
      // Left
      ctx.fillRect(this.px(-12)-size/2, this.py(dy)-size/2, size, size);
      // Right
      ctx.fillRect(this.px(W+12)-size/2, this.py(dy)-size/2, size, size);
    }

