        ctx.setLineDash([this.pr(10), this.pr(6)]);
        ctx.beginPath();
        ctx.moveTo(this.px(cue.x), this.py(cue.y));
        ctx.lineTo(this.px(aimLine.x), this.py(aimLine.y));
        ctx.stroke();
        ctx.setLineDash([]);
        // Power indicator
        const power = aimLine.power;
        ctx.fillStyle = `hsl(${Math.max(0, 120 - power * 1.2)}, 100%, 50%)`;
        ctx.fillRect(this.px(cue.x) - this.pr(30), this.py(cue.y) - this.pr(R + 18), this.pr(60) * power, this.pr(6));
        ctx.strokeStyle = '#fff8';
        ctx.strokeRect(this.px(cue.x) - this.pr(30), this.py(cue.y) - this.pr(R + 18), this.pr(60), this.pr(6));
      }
    }
  }

  _drawBall(b) {
    const ctx = this.ctx;
    const x = this.px(b.x);
    const y = this.py(b.y);
    const r = this.pr(R);

    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.beginPath();
    ctx.ellipse(x + this.pr(2), y + this.pr(2), r * 0.7, r * 0.25, 0, 0, Math.PI*2);
    ctx.fill();

    // Ball body
    const grad = ctx.createRadialGradient(
      x - r * 0.3, y - r * 0.3, r * 0.1,
      x, y, r
    );
    if (b.cue) {
      grad.addColorStop(0, '#fff');
      grad.addColorStop(0.6, '#ddd');
      grad.addColorStop(1, '#aaa');
    } else {
      // Solid color based on index (simplified 8-ball colors)
      const idx = this.engine.balls.indexOf(b);
      const colors = [
        '#ffd700', '#007fff', '#cc0000', '#800080', '#ff8c00',
        '#00aa00', '#8b0000', '#000', // 1-8
        '#ffd700', '#007fff', '#cc0000', '#800080', '#ff8c00',
        '#00aa00', '#8b0000'  // 9-15
      ];
      const base = colors[(idx - 1) % colors.length] || '#fff';
      const dark = this._darken(base);
      grad.addColorStop(0, this._lighten(base));
      grad.addColorStop(0.6, base);
      grad.addColorStop(1, dark);
    }
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI*2);
    ctx.fill();

    // Highlight
    ctx.fillStyle = 'rgba(255,255,255,0.3)';
    ctx.beginPath();
    ctx.arc(x - r*0.3, y - r*0.3, r*0.35, 0, Math.PI*2);
    ctx.fill();

    // Ball number for non-cue
    if (!b.cue) {
      const idx = this.engine.balls.indexOf(b);
      if (idx > 0) {
        const num = ((idx - 1) % 15) + 1;
        ctx.fillStyle = num <= 8 ? '#000' : '#fff';
        ctx.font = `bold ${this.pr(R*0.9)}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(num.toString(), x, y + this.pr(1));
      }
    }
  }

  _lighten(hex) {
    const c = parseInt(hex.slice(1), 16);
    const r = Math.min(255, (c>>16) + 60);
    const g = Math.min(255, ((c>>8)&255) + 60);
    const b = Math.min(255, (c&255) + 60);
    return `rgb(${r},${g},${b})`;
  }
  _darken(hex) {
    const c = parseInt(hex.slice(1), 16);
    const r = Math.max(0, (c>>16) - 60);
    const g = Math.max(0, ((c>>8)&255) - 60);
    const b = Math.max(0, (c&255) - 60);
    return `rgb(${r},${g},${b})`;
  }
}

// ============================================================
// INPUT HANDLER
// ============================================================
class InputHandler {
  constructor(canvas, engine, renderer) {
    this.canvas = canvas;
    this.engine = engine;
    this.renderer = renderer;
    this.dragging = false;
    this.dragStart = {x:0, y:0};
    this.currentDrag = null; // {x, y, power}
    this.canvas.addEventListener('mousedown', this.onDown.bind(this));
    window.addEventListener('mousemove', this.onMove.bind(this));
    window.addEventListener('mouseup', this.onUp.bind(this));
    // Touch support
    this.canvas.addEventListener('touchstart', this.onTouchStart.bind(this), {passive:false});
    window.addEventListener('touchmove', this.onTouchMove.bind(this), {passive:false});
    window.addEventListener('touchend', this.onTouchEnd.bind(this));
  }

  _getCanvasPoint(clientX, clientY) {
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: (clientX - rect.left) / this.renderer.scale - this.renderer.offsetX / this.renderer.scale,
      y: (clientY - rect.top) / this.renderer.scale - this.renderer.offsetY / this.renderer.scale
    };
  }

  onDown(e) {
    const pt = this._getCanvasPoint(e.clientX, e.clientY);
    const cue = this.engine.balls.find(b => b.cue && b.active);
    if (!cue) return;
    const dx = pt.x - cue.x;
    const dy = pt.y - cue.y;
    if (dx*dx + dy*dy <= R*R) {
      this.dragging = true;
      this.dragStart = {x: pt.x, y: pt.y};
      e.preventDefault();
    }
  }

  onMove(e) {
    if (!this.dragging) return;
    const pt = this._getCanvasPoint(e.clientX, e.clientY);
    this.currentDrag = this._computeDrag(pt);
  }

  onUp(e) {
    if (!this.dragging) return;
    this.dragging = false;
    if (this.currentDrag) {
      this.engine.shoot(this.currentDrag.vx, this.currentDrag.vy);
    }
    this.currentDrag = null;
  }

  onTouchStart(e) {
    if (e.touches.length !== 1) return;
    const t = e.touches[0];
    const pt = this._getCanvasPoint(t.clientX, t.clientY);
    const cue = this.engine.balls.find(b => b.cue && b.active);
    if (!cue) return;
    const dx = pt.x - cue.x;
    const dy = pt.y - cue.y;
    if (dx*dx + dy*dy <= R*R) {
      this.dragging = true;
      this.dragStart = {x: pt.x, y: pt.y};
      e.preventDefault();
    }
  }

  onTouchMove(e) {
    if (!this.dragging || e.touches.length !== 1) return;
    const t = e.touches[0];
    const pt = this._getCanvasPoint(t.clientX, t.clientY);
    this.currentDrag = this._computeDrag(pt);
    e.preventDefault();
  }

  onTouchEnd(e) {
    if (!this.dragging) return;
    this.dragging = false;
    if (this.currentDrag) {
      this.engine.shoot(this.currentDrag.vx, this.currentDrag.vy);
    }
    this.currentDrag = null;
  }

  _computeDrag(currentPt) {
    const cue = this.engine.balls.find(b => b.cue && b.active);
    if (!cue) return null;
    // Drag vector (from cue to mouse)
    const dx = currentPt.x - cue.x;
    const dy = currentPt.y - cue.y;
    const dist = Math.hypot(dx, dy);
    // Max drag distance for max power
    const maxDrag = 180;
    const clampedDist = Math.min(dist, maxDrag);
    const power = clampedDist / maxDrag; // 0..1
    // Shoot direction is OPPOSITE to drag (pull back)
    const dirX = -dx / (dist || 1);
    const dirY = -dy / (dist || 1);
    // Max speed ~ 500 px/s
    const maxSpeed = 500;
    const speed = power * maxSpeed;
    return {
      x: cue.x + dirX * clampedDist * 0.5, // aim line endpoint
      y: cue.y + dirY * clampedDist * 0.5,
      vx: dirX * speed,
      vy: dirY * speed,
      power
    };
  }

  getAimLine() {
    return this.currentDrag;
  }
}

