    engine.pause();
    pauseBtn.textContent = 'Resume';
  } else {
    engine.resume();
    pauseBtn.textContent = 'Pause';
  }
});

// Animation loop
let lastTime = performance.now();
function loop(now) {
  const dt = Math.min((now - lastTime) / 1000, 0.1); // clamp max dt
  lastTime = now;
  engine.step(dt);
  renderer.draw(input.getAimLine());
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

// Expose window.sim API
window.sim = {
  W, H, R,
  reset: (balls) => engine.reset(balls),
  step: (dt) => engine.step(dt),
  state: () => engine.state(),
  shoot: (vx, vy) => engine.shoot(vx, vy),
  pause: () => engine.pause(),
  resume: () => engine.resume()
};
</script>
